/// Consumes the SSE byte stream line by line under the stream-idle
/// watchdog (issue #1036 review round 1): codex bypasses the shared
/// [createSseIterator], so without this a connected-but-silent endpoint
/// hung the turn forever after headers arrived. No decoded line for
/// [effectiveProviderStreamIdleTimeout] errors the turn (the resolver can
/// fail over) and the finally-cancel detaches the byte pipeline — the
/// issue-#921 safe abandonment this bypass would otherwise lose. The
/// cancel token detaches at once too (issue #1121 review round 1): an
/// abort during a silent stretch must not wait for the next line or the
/// idle watchdog.
Future<void> _consumeSseLines(http.StreamedResponse response) async {
  // Issue #1554, review round 1: the model's request-scoped idle window
  // wins; WITHOUT a model override the same URL-keyed tuning table
  // createSseIterator consults applies (a streamIdleTimeoutMs-only
  // registry entry must scope the codex bypass too, not just the shared
  // iterator path).
  final tunedIdle = response.request?.url == null
      ? effectiveProviderStreamIdleTimeout
      : providerStreamIdleTimeoutForUrl(response.request!.url);
  final idle = model.streamIdleTimeout ?? tunedIdle;
  // The stall line names the override of THE LEG THAT RAN — an idle-only
  // model scope is named here; a model without a scoped idle leg keeps
  // the bare stall text (per-leg labels, review round 1).
  final scopedNote = model.streamIdleTimeout == null
      ? ''
      : ' — idle window ${idle.inSeconds}s (${model.timeoutScopeLabel})';
  final lines = StreamIterator<String>(
    response.stream.transform(utf8.decoder).transform(const LineSplitter()),
  );
  final token = [REDACTED:Sensitive Value];
  if (token != null) {
    // Same prompt-abort latency createSseIterator gives every other
    // adapter; the finally-cancel below stays as the backstop.
    unawaited(
      token.onCancel.then((_) async {
        await lines.cancel().catchError((_) {});
      }),
    );
  }
  try {
    while (await lines.moveNext().timeout(
      idle,
      onTimeout: () {
        // gh-1395 review round 1: the codex bypass's idle watchdog must
        // name the stall like every other watchdog — the pinned trace
        // line + the payload dump (the evidence stays replayable).
        providerIdleStallFired(response, idle);
        throw TimeoutException(
          'chatgpt-codex ${redactProviderUrl(_endpoint)} stalled: no SSE '
          'bytes for ${idle.inSeconds}s (stream idle timeout$scopedNote)',
        );
      },
    )) {
      cancelToken?.throwIfCancelled();
      _sse.add(lines.current, _handleEvent);
    }

