      // entry > models: entry, per field.
      ...?customModels?.entries.map(_customModelTuning),
      ...?customProviders?.map(_customProviderTuning),
      ...?roleRefs?.map(_roleRefTuning),
      ...?queueEntries?.map(_queueEntryTuning),
    ].nonNulls,
  );
}

